svg.script:
const BASE = "https:/" + "/cdn.jsdelivr.net/gh/jaromaz/jslinux-mobile@master/";
const frame = document.getElementById("linux_frame");

const shim = `<base href="${BASE}" /><script>
  console.log("[PASTE DEBUG] Shim loaded inside iframe!");

  try { window.localStorage.getItem("t"); } catch (e) {
    const mem = {};
    Object.defineProperty(window, "localStorage", { value: {
      getItem: k => mem[k] || null,
      setItem: (k, v) => { mem[k] = String(v); },
      removeItem: k => { delete mem[k]; },
      clear: () => { for (const k in mem) delete mem[k]; }
    }});
  }
  try { document.cookie; } catch (e) {
    let c = "";
    Object.defineProperty(document, "cookie", { get: () => c, set: v => { c = v; } });
  }

  async function handlePaste(e) {
    if ((e.ctrlKey || e.metaKey) && e.key && e.key.toLowerCase() === "v") {
      console.log("[PASTE DEBUG] Ctrl+V detected! Target:", e.target && e.target.tagName);
      e.preventDefault();
      e.stopImmediatePropagation();

      let text = "";
      try {
        text = await navigator.clipboard.readText();
        console.log("[PASTE DEBUG] Read from navigator.clipboard:", JSON.stringify(text));
      } catch (err) {
        console.warn("[PASTE DEBUG] navigator.clipboard failed:", err.message);
        text = window.prompt("Press Ctrl+V here and click OK to paste into Linux:") || "";
        console.log("[PASTE DEBUG] Read from prompt:", JSON.stringify(text));
      }

      if (!text) {
        console.warn("[PASTE DEBUG] No text to paste (empty).");
        return;
      }

      console.log("[PASTE DEBUG] Checking pc:", typeof pc, typeof pc !== "undefined" ? pc.serial : "no pc");
      console.log("[PASTE DEBUG] Checking window.term:", typeof window.term);

      const clean = text.split("\\r\\n").join("\\n").split("\\n").join("\\r");
      let idx = 0;

      const typer = setInterval(() => {
        if (idx >= clean.length) {
          console.log("[PASTE DEBUG] Finished sending all", clean.length, "chars.");
          clearInterval(typer);
          return;
        }
        const code = clean.charCodeAt(idx++);
        if (typeof pc !== "undefined" && pc.serial && typeof pc.serial.send_char === "function") {
          pc.serial.send_char(code);
        } else {
          console.error("[PASTE DEBUG] pc.serial.send_char is NOT available!");
          clearInterval(typer);
        }
      }, 40);
    }
  }

  window.addEventListener("keydown", handlePaste, true);
  document.addEventListener("keydown", handlePaste, true);
<\/script>`;

fetch(BASE + "index.html")
  .then(res => {
    if (!res.ok) throw new Error("HTTP " + res.status);
    return res.text();
  })
  .then(html => {
    const injected = html.replace(/<head[^>]*>/i, match => match + shim);
    const doc = frame.contentDocument || frame.contentWindow.document;
    doc.open();
    doc.write(injected);
    doc.close();
  })
  .catch(err => {
    const doc = frame.contentDocument || frame.contentWindow.document;
    doc.open();
    doc.write('<body style="background:#000;color:#0f0;font-family:monospace;padding:16px;">Error: ' + err.message + '</body>');
    doc.close();
  });
